package com.slayerlogger;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemVariationMapping;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.List;

/**
 * Tracks the task held in Slayer task storage and prints it to chat when the
 * player checks their slayer helm, ring, or gem.
 *
 * The stored task's monster and amount are not kept in any persistent client-side
 * varp. The server only sends them (in the generic IF4/IF5/IF6 varps) while the
 * Slayer Rewards interface is open, so the values are captured there and remembered
 * per RuneScape profile. The stored task's master and Mortimer modifier are
 * persistent varbits and are read live.
 */
@Slf4j
@Singleton
class StoredTaskTracker
{
	static final String STORED_NAME_KEY = "storedTaskName";
	static final String STORED_AMOUNT_KEY = "storedTaskAmount";

	// VarPlayerID.SLAYER_TARGET value meaning "boss task; see the boss id"
	private static final int BOSS_TASK_ID = 98;

	// Modifier ids from the SlayerModifiers DB table
	private static final int MODIFIER_POINTS = 1;
	private static final int MODIFIER_QUANTITY = 2;
	private static final int MODIFIER_CLUES = 3;
	private static final int MODIFIER_SUPERIOR = 4;
	private static final int MODIFIER_XP = 5;

	// Ticks to wait for the game's own check response before printing anyway
	private static final int CHECK_TIMEOUT_TICKS = 3;

	private final Client client;
	private final ClientThread clientThread;
	private final ConfigManager configManager;
	private final ChatMessageManager chatMessageManager;
	private final SlayerLoggerConfig config;

	// Set when the player clicks Check on a slayer item; cleared once the storage line is printed
	private boolean awaitingCheckResponse;
	private int checkTicks;

	@Inject
	StoredTaskTracker(Client client, ClientThread clientThread, ConfigManager configManager,
		ChatMessageManager chatMessageManager, SlayerLoggerConfig config)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.configManager = configManager;
		this.chatMessageManager = chatMessageManager;
		this.config = config;
	}

	void reset()
	{
		awaitingCheckResponse = false;
		checkTicks = 0;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			reset();
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.SLAYER_REWARDS)
		{
			clientThread.invokeLater(this::captureStoredTask);
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		int varpId = event.getVarpId();
		if (varpId != VarPlayerID.IF4 && varpId != VarPlayerID.IF5 && varpId != VarPlayerID.IF6)
		{
			return;
		}
		// IF4-6 are shared scratch varps; they only describe the stored task while the rewards screen is open
		if (client.getWidget(InterfaceID.SlayerRewards.UNIVERSE) != null)
		{
			clientThread.invokeLater(this::captureStoredTask);
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (!config.showStoredTaskOnCheck())
		{
			return;
		}
		if ((event.getMenuAction() != MenuAction.CC_OP && event.getMenuAction() != MenuAction.CC_OP_LOW_PRIORITY)
			|| !"Check".equals(event.getMenuOption()))
		{
			return;
		}

		Widget w = client.getWidget(event.getParam1());
		if (w == null)
		{
			return;
		}
		if (event.getParam0() != -1)
		{
			w = w.getChild(event.getParam0());
			if (w == null)
			{
				return;
			}
		}

		// The equipment interface keeps the item on a dynamic child component
		int itemId = w.getItemId();
		for (Widget child : w.getDynamicChildren())
		{
			if (itemId == -1)
			{
				itemId = child.getItemId();
			}
		}

		itemId = ItemVariationMapping.map(itemId);
		if (itemId == ItemID.SLAYER_HELM || itemId == ItemID.SLAYER_RING_8 || itemId == ItemID.SLAYER_GEM)
		{
			awaitingCheckResponse = true;
			checkTicks = 0;
		}
	}

	// Print the storage line right after the game's own check response so it reads in order
	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (awaitingCheckResponse && event.getType() == ChatMessageType.GAMEMESSAGE)
		{
			printStoredTask();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (awaitingCheckResponse && ++checkTicks >= CHECK_TIMEOUT_TICKS)
		{
			printStoredTask();
		}
	}

	private void captureStoredTask()
	{
		if (client.getWidget(InterfaceID.SlayerRewards.UNIVERSE) == null)
		{
			return;
		}

		int amount = client.getVarpValue(VarPlayerID.IF4);
		int target = client.getVarpValue(VarPlayerID.IF5);
		int bossId = client.getVarpValue(VarPlayerID.IF6);

		// Mirrors the rewards interface script: a stored task exists when the target is set
		// and the amount is positive (or -1 for an unlimited boss task)
		boolean hasTask = target != 0 && (amount > 0 || (target == BOSS_TASK_ID && amount == -1));
		if (!hasTask)
		{
			if (getStoredName() != null)
			{
				log.debug("Task storage is now empty");
			}
			configManager.setRSProfileConfiguration(SlayerLoggerConfig.GROUP, STORED_NAME_KEY, "");
			configManager.setRSProfileConfiguration(SlayerLoggerConfig.GROUP, STORED_AMOUNT_KEY, 0);
			return;
		}

		String name = lookupTaskName(target, bossId);
		if (name == null)
		{
			log.debug("Could not resolve stored task name for target {} boss {}", target, bossId);
			return;
		}

		configManager.setRSProfileConfiguration(SlayerLoggerConfig.GROUP, STORED_NAME_KEY, name);
		configManager.setRSProfileConfiguration(SlayerLoggerConfig.GROUP, STORED_AMOUNT_KEY, amount);
		log.debug("Captured stored task: {} x {}", amount, name);
	}

	private String lookupTaskName(int target, int bossId)
	{
		int taskRow;
		if (target == BOSS_TASK_ID)
		{
			List<Integer> bossRows = client.getDBRowsByValue(
				DBTableID.SlayerTaskSublist.ID, DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID, 0, bossId);
			if (bossRows.isEmpty())
			{
				return null;
			}
			taskRow = (Integer) client.getDBTableField(bossRows.get(0), DBTableID.SlayerTaskSublist.COL_TASK, 0)[0];
		}
		else
		{
			List<Integer> taskRows = client.getDBRowsByValue(
				DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, 0, target);
			if (taskRows.isEmpty())
			{
				return null;
			}
			taskRow = taskRows.get(0);
		}
		return (String) client.getDBTableField(taskRow, DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0)[0];
	}

	// Returns null when storage has never been synced, "" when it was last seen empty
	private String getStoredName()
	{
		return configManager.getRSProfileConfiguration(SlayerLoggerConfig.GROUP, STORED_NAME_KEY);
	}

	private void printStoredTask()
	{
		awaitingCheckResponse = false;
		checkTicks = 0;

		String name = getStoredName();
		String text;
		if (name == null)
		{
			text = "Storage: unknown - open a Slayer master's Rewards screen once to sync.";
		}
		else if (name.isEmpty())
		{
			text = "Storage: empty.";
		}
		else
		{
			Integer amount = configManager.getRSProfileConfiguration(SlayerLoggerConfig.GROUP, STORED_AMOUNT_KEY, Integer.class);
			StringBuilder sb = new StringBuilder("Storage: ");
			if (amount != null && amount > 0)
			{
				sb.append(amount).append(" x ");
			}
			sb.append(name);
			String modifier = describeStoredModifier();
			if (!modifier.isEmpty())
			{
				sb.append(' ').append(modifier);
			}
			sb.append('.');
			text = sb.toString();
		}

		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.runeLiteFormattedMessage(text)
			.build());
	}

	// Formats the stored task's Mortimer modifier the same way the rewards interface does
	private String describeStoredModifier()
	{
		int id = client.getVarbitValue(VarbitID.SLAYER_MODIFIER_ID_STORED);
		int value = client.getVarbitValue(VarbitID.SLAYER_MODIFIER_VALUE_STORED);
		boolean negative = client.getVarbitValue(VarbitID.SLAYER_MODIFIER_NEGATIVE_STORED) == 1;
		switch (id)
		{
			case MODIFIER_POINTS:
				return "(+" + value + " Slayer points)";
			case MODIFIER_QUANTITY:
				return "(" + (negative ? "-" : "+") + value + " quantity)";
			case MODIFIER_CLUES:
				return "(+" + value + "% Clue chance)";
			case MODIFIER_SUPERIOR:
				return "(+" + value + "% Superior unique chance)";
			case MODIFIER_XP:
				return "(+" + value + "% Slayer XP)";
			default:
				return "";
		}
	}
}

package com.slayerlogger;

import com.google.gson.Gson;
import com.google.inject.Provides;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.RuneLite;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.Text;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

import javax.inject.Inject;
import java.io.FileWriter;
import java.io.IOException;
import java.io.PrintWriter;
import java.nio.file.Path;
import java.time.Instant;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

@Slf4j
@PluginDescriptor(
	name = "Slayer Task Logger",
	description = "Logs slayer task assignments and completions to a file and notifies Dink",
	tags = {"slayer", "log", "task", "tracker"}
)
public class SlayerLoggerPlugin extends Plugin
{
	// "Your new task is to kill 135 blue dragons."
	// Some masters append a bonus point line: "Your new task is to kill 184 Aquanites.<br>Completing this
	// task will award 30 bonus Slayer Points." — the monster group is lazy so it stops at the first period.
	// The bonus amount is ignored; the actual points awarded arrive with the completion message.
	private static final Pattern TASK_RECEIVED_PATTERN = Pattern.compile(
		"Your new task is to kill (\\d+) (.+?)\\."
	);

	// Konar: "You are to bring balance to 128 Fire Giants in the Giants' Den."
	// or:   "You are to bring balance to 152 Jellies in Tapoyauik."
	private static final Pattern TASK_RECEIVED_KONAR_PATTERN = Pattern.compile(
		"You are to bring balance to (\\d+) (.+?) in (?:the )?.+\\."
	);

	// First chat message on task completion: "You have completed your task! You killed 267 Nechryael. You gained 56,280 xp"
	private static final Pattern TASK_COMPLETE_PART1_PATTERN = Pattern.compile(
		"You have completed your task! You killed (\\d+) (.+?)\\. You gained ([\\d,]+) (?:Slayer )?[Xx][Pp]\\.?"
	);

	// Second chat message on task completion: "You've completed 3,733 tasks and received 15 points, giving you a total of 2,983; return to a Slayer master."
	// Some masters name themselves and track their own count: "You've completed 1 Mortimer task and received 30 points, giving you a total of 1,619; return to a Slayer master."
	// The points clause is absent when no points are awarded (Mortimer without the points modifier, Turael,
	// streaks under 5): "You've completed 2 Mortimer tasks; return to a Slayer master."
	private static final Pattern TASK_COMPLETE_PART2_PATTERN = Pattern.compile(
		"You'?ve completed (?:at least )?([\\d,]+) (?:([A-Za-z][A-Za-z' -]*?) )?tasks?(?: and received ([\\d,]+) points?, giving you a total of ([\\d,]+))?(?:;|\\.|$)"
	);

	// Ticks to wait for the second completion message before logging the completion from varbits alone
	private static final int COMPLETION_PART2_TIMEOUT_TICKS = 2;

	// VarbitID.SLAYER_MASTER value for Mortimer, who tracks his own task count in a varp
	private static final int MORTIMER_SLAYER_MASTER = 10;

	// TzHaar task special upgrade prompt
	private static final String TZHAAR_UPGRADE_TEXT = "Ah... Tzhaar...";

	// Accepted the Jad/Zuk upgrade
	private static final String TZHAAR_UPGRADE_ACCEPTED_TEXT = "A wise choice";

	// Task cancelled message (GAMEMESSAGE or DIALOG)
	private static final String TASK_CANCELLED_TEXT = "Your task has been cancelled.";

	// Superior creature spawn (GAMEMESSAGE)
	private static final String SUPERIOR_SPAWN_TEXT = "A superior foe has appeared...";

	// Slayer cape perk proc dialog (standard masters)
	private static final String CAPE_PERK_PROC_TEXT = "I might be able to do you a favour if you want";

	// Slayer cape perk proc dialog (Konar)
	private static final String CAPE_PERK_PROC_TEXT_KONAR = "I can reward that";

	private static final DateTimeFormatter FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");
	private static final MediaType JSON = MediaType.get("application/json; charset=utf-8");

	@Inject
	private Gson gson;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private EventBus eventBus;

	@Inject
	private OkHttpClient httpClient;

	@Inject
	private SlayerLoggerConfig config;

	@Inject
	private StoredTaskTracker storedTaskTracker;

	private PrintWriter logWriter;

	// Current task state — kept in sync via varbits so skip/cape proc always have correct data
	private String currentTaskName = "";
	private int currentOriginalAmount;
	private String currentArea = "";
	private int currentPoints;
	private int currentTasksCompleted;
	private int currentSlayerMaster;

	// Pending state for the two-part task completion chat message
	private boolean awaitingCompletionPart2 = false;
	private int pendingKillCount;
	private String pendingMonster;
	private String pendingXp;
	private int pendingTicks;

	// Set when the TzHaar upgrade prompt is shown, cleared on choice or next task
	private boolean awaitingTzhaarChoice = false;

	@Override
	protected void startUp() throws Exception
	{
		Path pluginDir = RuneLite.RUNELITE_DIR.toPath().resolve("slayer-task-logger");
		pluginDir.toFile().mkdirs();
		Path logPath = pluginDir.resolve("slayer-log.txt");
		try
		{
			logWriter = new PrintWriter(new FileWriter(logPath.toFile(), true), true);
			log.debug("Slayer Logger started, logging to {}", logPath);
		}
		catch (IOException e)
		{
			log.error("Failed to open slayer log file at {}", logPath, e);
		}

		eventBus.register(storedTaskTracker);

		if (client.getGameState() == GameState.LOGGED_IN)
		{
			clientThread.invoke(this::syncCurrentTask);
		}
	}

	@Override
	protected void shutDown() throws Exception
	{
		if (logWriter != null)
		{
			logWriter.close();
			logWriter = null;
		}
		awaitingCompletionPart2 = false;
		eventBus.unregister(storedTaskTracker);
		storedTaskTracker.reset();
		log.debug("Slayer Logger stopped!");
	}

	// Silently syncs current task state from game memory — no notifications fired.
	// Covers: plugin enabled mid-session, login, world hop, stored task swaps.
	private void syncCurrentTask()
	{
		currentPoints = client.getVarbitValue(VarbitID.SLAYER_POINTS);
		currentTasksCompleted = client.getVarbitValue(VarbitID.SLAYER_TASKS_COMPLETED);
		currentSlayerMaster = client.getVarbitValue(VarbitID.SLAYER_MASTER);

		int amount = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
		if (amount > 0)
		{
			String taskName = lookupTaskName();
			if (taskName != null)
			{
				currentTaskName = taskName.toLowerCase();
				currentOriginalAmount = client.getVarpValue(VarPlayerID.SLAYER_COUNT_ORIGINAL);
				currentArea = lookupAreaName();
			}
		}
	}

	private String lookupAreaName()
	{
		int areaId = client.getVarpValue(VarPlayerID.SLAYER_AREA);
		if (areaId <= 0)
		{
			return "";
		}
		List<Integer> areaRows = client.getDBRowsByValue(
			DBTableID.SlayerArea.ID, DBTableID.SlayerArea.COL_AREA_ID, 0, areaId);
		if (areaRows.isEmpty())
		{
			return "";
		}
		return (String) client.getDBTableField(areaRows.get(0), DBTableID.SlayerArea.COL_AREA_NAME_IN_HELPER, 0)[0];
	}

	private String lookupTaskName()
	{
		int taskId = client.getVarpValue(VarPlayerID.SLAYER_TARGET);
		int taskDBRow;

		if (taskId == 98) // Boss task
		{
			List<Integer> bossRows = client.getDBRowsByValue(
				DBTableID.SlayerTaskSublist.ID,
				DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID,
				0,
				client.getVarbitValue(VarbitID.SLAYER_TARGET_BOSSID));
			if (bossRows.isEmpty())
			{
				return null;
			}
			taskDBRow = (Integer) client.getDBTableField(bossRows.get(0), DBTableID.SlayerTaskSublist.COL_TASK, 0)[0];
		}
		else
		{
			List<Integer> taskRows = client.getDBRowsByValue(
				DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, 0, taskId);
			if (taskRows.isEmpty())
			{
				return null;
			}
			taskDBRow = taskRows.get(0);
		}

		return (String) client.getDBTableField(taskDBRow, DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0)[0];
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			clientThread.invoke(this::syncCurrentTask);
		}
		else if (event.getGameState() == GameState.LOGIN_SCREEN
			|| event.getGameState() == GameState.HOPPING)
		{
			currentTaskName = "";
			awaitingCompletionPart2 = false;
			awaitingTzhaarChoice = false;
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		int varpId = event.getVarpId();
		int varbitId = event.getVarbitId();

		if (varpId == VarPlayerID.SLAYER_TARGET
			|| varpId == VarPlayerID.SLAYER_COUNT
			|| varpId == VarPlayerID.SLAYER_COUNT_ORIGINAL
			|| varpId == VarPlayerID.SLAYER_AREA
			|| varbitId == VarbitID.SLAYER_TARGET_BOSSID)
		{
			clientThread.invokeLater(this::syncCurrentTask);
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage chatMessage)
	{
		ChatMessageType type = chatMessage.getType();

		if (type != ChatMessageType.GAMEMESSAGE
			&& type != ChatMessageType.SPAM
			&& type != ChatMessageType.DIALOG
			&& type != ChatMessageType.MESBOX)
		{
			return;
		}

		String message = Text.removeTags(chatMessage.getMessage());

		if ((type == ChatMessageType.DIALOG || type == ChatMessageType.MESBOX)
			&& message.contains(TZHAAR_UPGRADE_TEXT))
		{
			handleTzhaarTaskAssigned();
			return;
		}

		if (awaitingTzhaarChoice
			&& (type == ChatMessageType.DIALOG || type == ChatMessageType.MESBOX)
			&& message.contains(TZHAAR_UPGRADE_ACCEPTED_TEXT))
		{
			handleTzhaarUpgradeAccepted();
			return;
		}

		if (message.contains(CAPE_PERK_PROC_TEXT) || message.contains(CAPE_PERK_PROC_TEXT_KONAR))
		{
			handleCapePerkProc();
			return;
		}

		if (message.contains(TASK_CANCELLED_TEXT))
		{
			handleTaskSkipped();
			return;
		}

		if (message.contains(SUPERIOR_SPAWN_TEXT))
		{
			handleSuperiorSpawn();
			return;
		}

		Matcher taskReceived = TASK_RECEIVED_PATTERN.matcher(message);
		if (taskReceived.find())
		{
			int count = Integer.parseInt(taskReceived.group(1));
			String monster = taskReceived.group(2);
			handleTaskReceived(count, monster);
			return;
		}

		Matcher taskReceivedKonar = TASK_RECEIVED_KONAR_PATTERN.matcher(message);
		if (taskReceivedKonar.find())
		{
			int count = Integer.parseInt(taskReceivedKonar.group(1));
			String monster = taskReceivedKonar.group(2);
			handleTaskReceived(count, monster);
			return;
		}

		Matcher part1 = TASK_COMPLETE_PART1_PATTERN.matcher(message);
		if (part1.find())
		{
			pendingKillCount = Integer.parseInt(part1.group(1));
			pendingMonster = part1.group(2);
			pendingXp = part1.group(3);
			pendingTicks = 0;
			awaitingCompletionPart2 = true;
			return;
		}

		if (awaitingCompletionPart2)
		{
			Matcher part2 = TASK_COMPLETE_PART2_PATTERN.matcher(message);
			if (part2.find())
			{
				awaitingCompletionPart2 = false;
				int tasksCompleted = Integer.parseInt(part2.group(1).replace(",", ""));
				String masterName = part2.group(2) == null ? "" : part2.group(2);
				// No points clause means no points were awarded for this task
				int pointsReceived = part2.group(3) == null ? 0 : Integer.parseInt(part2.group(3).replace(",", ""));
				String totalPoints = part2.group(4) == null
					? String.valueOf(client.getVarbitValue(VarbitID.SLAYER_POINTS))
					: part2.group(4);
				handleTaskComplete(pendingKillCount, pendingMonster, pendingXp, tasksCompleted, masterName, pointsReceived, totalPoints);
			}
			else
			{
				log.debug("Unmatched message while awaiting completion part 2: {}", message);
			}
		}
	}

	// If the second completion message never matches (unknown wording), log the completion from varbits
	// so a task is never silently dropped.
	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!awaitingCompletionPart2)
		{
			return;
		}
		if (++pendingTicks < COMPLETION_PART2_TIMEOUT_TICKS)
		{
			return;
		}
		awaitingCompletionPart2 = false;

		int master = client.getVarbitValue(VarbitID.SLAYER_MASTER);
		String masterName;
		int tasksCompleted;
		if (master == MORTIMER_SLAYER_MASTER)
		{
			masterName = "Mortimer";
			tasksCompleted = client.getVarpValue(VarPlayerID.SLAYER_MORTIMER_TASKS_COMPLETED);
		}
		else
		{
			masterName = "";
			tasksCompleted = client.getVarbitValue(VarbitID.SLAYER_TASKS_COMPLETED);
		}
		String totalPoints = String.valueOf(client.getVarbitValue(VarbitID.SLAYER_POINTS));
		log.debug("Completion part 2 not received; logging completion from varbits");
		handleTaskComplete(pendingKillCount, pendingMonster, pendingXp, tasksCompleted, masterName, 0, totalPoints);
	}

	private void handleTaskReceived(int count, String monster)
	{
		awaitingTzhaarChoice = false;
		currentTaskName = monster;
		currentOriginalAmount = count;
		currentArea = lookupAreaName();

		int livePoints = client.getVarbitValue(VarbitID.SLAYER_POINTS);
		int liveTasksCompleted = client.getVarbitValue(VarbitID.SLAYER_TASKS_COMPLETED);
		currentPoints = livePoints;
		currentTasksCompleted = liveTasksCompleted;

		String areaStr = currentArea.isEmpty() ? "" : " | Area: " + currentArea;
		String entry = String.format("[%s] TASK RECEIVED: %s x%d%s | Tasks: %d | Points: %d",
			LocalDateTime.now().format(FORMATTER), monster, count, areaStr,
			liveTasksCompleted, livePoints);
		writeLog(entry);

		if (config.dinkOnTaskReceived())
		{
			sendDinkNotification(
				"Slayer Task Received",
				String.format("New task: %s x%d", monster, count)
			);
		}

		Map<String, Object> payload = new LinkedHashMap<>();
		payload.put("username", getPlayerName());
		payload.put("timestamp", Instant.now().toString());
		payload.put("message_type", "new task");
		payload.put("monster", monster);
		payload.put("amount", count);
		payload.put("area", currentArea);
		payload.put("tasks_completed", liveTasksCompleted);
		payload.put("total_points", livePoints);
		sendWebhook(payload);
	}

	private void handleTzhaarTaskAssigned()
	{
		awaitingTzhaarChoice = true;
		String taskName = lookupTaskName();
		if (taskName == null)
		{
			return;
		}
		int amount = client.getVarpValue(VarPlayerID.SLAYER_COUNT_ORIGINAL);
		handleTaskReceived(amount, taskName.toLowerCase());
	}

	private void handleTzhaarUpgradeAccepted()
	{
		awaitingTzhaarChoice = false;
		String newTaskName = lookupTaskName();
		if (newTaskName == null)
		{
			return;
		}
		newTaskName = newTaskName.toLowerCase();
		int newAmount = client.getVarpValue(VarPlayerID.SLAYER_COUNT_ORIGINAL);
		if (!newTaskName.equals(currentTaskName))
		{
			handleTaskReceived(newAmount, newTaskName);
		}
	}

	private void handleTaskSkipped()
